command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
Set-Location -LiteralPath $repo
& git fetch origin work/physical-drag-start-20261005 --no-tags --prune
if($LASTEXITCODE -ne 0){throw "candidate fetch failed"}
$temp=Join-Path $env:RUNNER_TEMP ("physical-drag-docs-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
  & git worktree add --detach $temp ba3baec0c302ba6eb77b5fe5ab65a91ebd374f02
  if($LASTEXITCODE -ne 0){throw "candidate worktree failed"}
  Set-Location -LiteralPath $temp
  & python -X utf8 tools\winui\run_checks.py fast --before 9e1b8be9f6b61ed8fc69519d281a9fe8bd2f1bc5 --head ba3baec0c302ba6eb77b5fe5ab65a91ebd374f02
  if($LASTEXITCODE -ne 0){throw "docs-only FAST validation failed"}
  Write-Host "PHYSICAL_DRAG_DOCS_FINAL=PASS"
} finally {
  Set-Location -LiteralPath $repo
  if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
  & git worktree prune
}
